  RV = `Sin categoría`,
  zV = `Tal vez fue su jugabilidad inmersiva, o su apasionante historia... sus personajes bien delineados, su diseño impecable o el multijugador adictivo. Cualquiera que sea la razón, el ganador del Premio al Juego del Año 2020 es un clásico instantáneo.`,
  BV = `El Juego de RV del Año no se presenta simplemente como una realidad normal. Este juego perfecciona la realidad, aprovechando el medio de la RV y superando los límites del entorno virtual.`,
  VV = `Este juego lleva publicado algún tiempo. Ya hace mucho que el equipo dejó atrás la primera presentación de su retoño creativo, pero siendo los buenos padres que son, estos desarrolladores continúan nutriendo y apoyando a su creación. Después de todos estos años, este juego aún sigue recibiendo nuevo contenido.`,
  HV = `Hay algunos juegos que no son igual de entretenidos cuando los juegas solo. Quizás necesites tener un amigo que te cubra las espaldas. Tal vez necesites tener un amigo al que apuñalar por la espalda. Sea lo que sea, la diversión espera a quienes se reúnen con sus amigos para jugar estos juegos.`,
  UV = `El estilo visual no aspira a una representación gráfica fiel del mundo real (aunque es un noble objetivo en sí mismo)… describe un aspecto y un comportamiento distintivos que impregnan un juego al completo.`,
  WV = `Los creadores de este juego están a la vanguardia de la experimentación creativa, ofreciendo nuevas perspectivas y sorpresas alucinantes. Este juego encantó, inspiró y entretuvo con sus elementos originales.`,
  GV = `Este es el juego que premia la perseverancia. No es para todos. Es el juego más difícil que jamás hemos amado.`,
  KV = `Este héroe anónimo merece ser reconocido por su excepcional banda sonora. ¡Es definitivamente la mejor! `,
  qV = `Algunos días solo te llena un juego con mucha narrativa, y la de este es contundente. Te engancha como una telenovela y está afinado como el guion de una serie de prestigio. ¡Bravísimo... por hacernos sentir cosas!`,
  JV = `Este juego es el antídoto perfecto contra un día ajetreado: es tranquilo, relajante y hace que tus preocupaciones se desvanezcan. Es tu momento zen.`,
  YV = `¿Quieres cambiar tu nominación?`,
