  pH = `Siéntate y Relájate`,
  mH = `Tal vez fue su jugabilidad inmersiva o su apasionante historia, sus personajes bien creados, su diseño inmaculado o su adictivo modo multijugador. Cualquiera que sea la razón, el ganador del premio al Mejor Juego del Año es un clásico instantáneo.`,
  hH = `El Juego de RV del Año no se presenta simplemente como una realidad normal. Este juego perfecciona la realidad, aprovechando el medio de la RV y superando los límites del entorno virtual.`,
  gH = `Este juego ha estado disponible durante un tiempo. Atrás quedaron los días en que los creadores de este juego anunciaron el debut de su bebé creativo, pero como son buenos padres, continuaron desarrollando y apoyando su creación. Este juego, actualmente, todavía recibe nuevo contenido incluso después de todos estos años.`,
  _H = `Hay algunos juegos que no son igual de entretenidos cuando los juegas solo. Quizás necesites tener un amigo que te cubra las espaldas. Tal vez necesites tener un amigo al que apuñalar por la espalda. Sea lo que sea, la diversión espera a quienes se reúnen con sus amigos para jugar estos juegos.`,
