  yH = `Los diseñadores de este juego están a la vanguardia de la experimentación creativa, ofreciendo nuevas perspectivas y sorpresas alucinantes. Este juego encantó, inspiró y entretuvo gracias a sus elementos originales.`,
  bH = `Este es el juego que premia la perseverancia. No es para todos. Es el juego más difícil que jamás hemos amado.`,
