  RH = `Hay algunos juegos que no son igual de entretenidos cuando los juegas solo. Quizás necesites tener un amigo que te cubra las espaldas. Tal vez necesites tener un amigo al que apuñalar por la espalda. Sea lo que sea, la diversión espera a quienes se reúnen con sus amigos para jugar a estos juegos.`,
