  UH = `Algunos días, solo un juego con mucha narración dará en el clavo, y este pega fuerte. Es tan apasionante como cualquier telenovela y tan bien afinado como un guion de TV de prestigio. ¡Bravísimo por hacernos sentir así!`,
  WH = `Este juego es el antídoto perfecto contra un día ajetreado: es tranquilo, relajante y hace que tus preocupaciones se desvanezcan. Es tu momento zen.`,
  GH = `Este juego te gustó tanto que te lo querías llevar a todas partes. ¡Y eso hiciste! Por suerte, todo lo que te hacía jugar sin parar en tu escritorio te enganchó aún más en el dispositivo portátil.`,
