  gU = `Has recibido %1$s fichas`,
  _U = `Tu saldo`,
  vU = `%1$s fichas`,
  yU = `No se puede abrir el sobre`,
  bU = `LA GRAN CARRERA DEL EMPERADOR`,
  xU = `El origen del horóscopo chino`,
  SU = `Parte I de IV`,
  CU = `Parte II de IV`,
  wU = `Parte III de IV`,
  TU = `Parte IV de IV`,
  EU = `El Emperador de Jade invocó a todas las criaturas de su reino a competir en una carrera hacia la corte celestial, declarando que los primeros doce en llegar serían honrados con un lugar en su nuevo calendario.

La inteligente Rata fue la primera en cruzar el río y llegar al dominio celestial. No le gustaba nadar, por lo que se había subido al lomo del confiable Buey, saltando entusiasmada al jardín celestial del Emperador, justo antes de que Buey llegara a la orilla. 

El constante Buey cruzó el río con facilidad, sin preocuparse por los resultados de la carrera, satisfecho por su papel en el éxito de Rata.`,
  DU = `El autosuficiente Tigre, viajó con demasiado cuidado para superar a Buey, pensando que quedar tercero era mejor que nada.

El veloz Conejo se encontró enseguida flotando sin rumbo. Pero la suerte le valió más que la estrategia, pues un viento favorable impulsó su embarcación improvisada de manera segura hacia la orilla.

La ventaja de Dragón volador reveló una población que lo necesitaba, y se detuvo para ayudar, además de regalarle una racha de viento a Conejo en el río. El honor era mucho más importante que la victoria, así encontró Dragón que la quinta posición le iba bien.`,
  OU = `La sigilosa Serpiente no estaba muy interesada en esforzarse demasiado, así que se enrolló alrededor de una de las pezuñas de Caballo sin que nadie lo notara.

Mientras Caballo galopaba hacia la línea de meta, Serpiente se desenrolló, asustando al corcel lo suficiente como para arrastrarse hacia la sexta posición con el temeroso Caballo trotando inmediatamente detrás de ella.`,
  kU = `Cabra, Mono y Gallo trabajaron juntos, pero dejaron que Cabra reclamara la octava posición, como recompensa por la ayuda durante el viaje. Mono obtuvo la novena posición y Gallo la décima, orgulloso de que el orden fuera justo.

El juguetón Perro estaba más interesado en revolcarse que en ganar, por lo que terminar undécimo fue un buen negocio considerando toda la diversión.

Cerdo llegó el último, ya que se había detenido para comer y dormir; siendo lo suficientemente sabio como para saber que cada animal tendría su momento con el Emperador.`,
  AU = `Los cambios en el perfil tendrán efecto tras su revisión`,
