  nme = `Los huecos en el gráfico (p.\xA0ej., entre %1$s y %2$s\xA0FPS) pueden deberse a la sincronización vertical (VSync), que sincroniza la entrega de fotogramas con la frecuencia de actualización de la pantalla para evitar el desgarro de la imagen. Esto puede hacer que las muestras se concentren en %1$s y %2$s\xA0FPS, incluso cuando la velocidad de fotogramas media del juego se sitúa entre ambos valores. Este es el comportamiento esperado de la sincronización vertical y, aunque puede afectar al ritmo de fotogramas, no necesariamente provoca tirones apreciables.`,
